select energy_manager.load_cards($cards$[
{"id":"p4-b01-035","paper":4,"topic":"Boiler Performance","kind":"problem","front":"Using the 79% efficient oil boiler (GCV 10,000 kcal/kg, steam enthalpy 665 kcal/kg, feed water 85 °C), find the evaporation ratio and the fuel oil consumed per tonne of steam.","back":"Evaporation ratio = 13.62 kg steam per kg oil. Fuel = 73.42 kg oil per tonne of steam.","explain":"Evaporation ratio is efficiency times GCV, divided by the heat added to each kg of feed water. Fuel per tonne is 1000 divided by the ratio.","flash":false,"source":"BEE Book 4 Ch 01 p44","steps":[{"prompt":"Write the evaporation ratio formula.","answer":"ER = (efficiency x GCV) / (h_steam - h_feed)","explain":"Heat in steam per kg of fuel = efficiency x GCV. Dividing by the heat added per kg steam (h - h_feed) gives kg steam per kg fuel."},{"prompt":"Substitute the values.","answer":"ER = (0.79 x 10000) / (665 - 85) = 13.62 kg steam/kg oil","explain":"665 - 85 = 580 kcal/kg, the heat added to each kg of feed water."},{"prompt":"Find fuel per tonne of steam.","answer":"1000 / 13.62 = 73.42 kg oil per tonne of steam","explain":"Fuel per tonne is the reciprocal of the evaporation ratio, scaled to 1000 kg of steam."}],"order":4114},
{"id":"p4-b01-036","paper":4,"topic":"Boiler Performance","kind":"problem","front":"Using 73.42 kg of fuel oil per tonne of steam at Rs 43/kg, with a 15% add-on for auxiliaries and consumables, what is the in-house cost of steam per tonne?","back":"About Rs 3,600 per tonne (book value). Recalculating 73.42 x 1.15 x 43 gives about Rs 3,630.","explain":"Steam cost = fuel cost plus 15% for auxiliaries and consumables. The book rounds to Rs 3,600, but its printed intermediate figure (Rs 3,599) does not match its own inputs, so check the arithmetic if asked for an exact value.","flash":false,"source":"BEE Book 4 Ch 01 p44","steps":[{"prompt":"Find the fuel cost per tonne of steam.","answer":"73.42 kg x Rs 43/kg = Rs 3,157 per tonne (approx.)","explain":"Fuel cost is the physical fuel quantity multiplied by its price."},{"prompt":"Add 15% for auxiliaries and consumables.","answer":"Cost = 73.42 x 1.15 x 43 = about Rs 3,630 per tonne; book quotes Rs 3,600 per tonne","explain":"The 15% covers auxiliary power and consumables, which are not in the fuel cost alone."}],"order":4115},
{"id":"p4-b01-037","paper":4,"topic":"Boiler Performance","kind":"problem","front":"A neighbouring plant offers steam at Rs 3,300 per tonne (condensate returned). In-house steam costs about Rs 3,600 per tonne. The unit buys 3,000 tonnes of steam per month. What is the cost advantage per tonne and the annual saving?","back":"Advantage = Rs 300 per tonne. Annual saving = Rs 108 lakh (Rs 1.08 crore).","explain":"Savings are the per-tonne difference times monthly volume times 12 months. This is the basis for a make-or-buy decision on steam.","flash":false,"source":"BEE Book 4 Ch 01 p44","steps":[{"prompt":"Find the cost advantage per tonne.","answer":"Rs 3,600 - Rs 3,300 = Rs 300 per tonne","explain":"Positive difference means buying steam is cheaper than generating it in-house."},{"prompt":"Find the annual saving.","answer":"Rs 300 x 3,000 t/month x 12 months = Rs 1,08,00,000 = Rs 108 lakh per year","explain":"1 lakh = Rs 100,000. The result is shown in the book as Rs 108 lakhs."}],"order":4116},
{"id":"p4-b01-038","paper":4,"topic":"Boiler Performance","kind":"problem","front":"In a boiler with 3.5 m/s wind, surface temperature 70 °C, ambient 31 °C, and surface area 90 m², find the radiation and convection loss per hour and its percentage of heat input (3501 kcal/kg coal; 5600 kg/h coal).","back":"Loss = 72,572 kcal/h, which is 0.37% of heat input.","explain":"The book calculates the surface loss from the formula using wind velocity and temperatures in Kelvin, converts W/m2 to kcal/m2 h with 0.86, then multiplies by surface area. It is then compared with total heat input per hour.","flash":false,"source":"BEE Book 4 Ch 01 p33","steps":[{"prompt":"Find the radiation and convection loss per m2 (W/m2) from the formula.","answer":"L6 = 0.548 x [(343/55.55)^4 - (304/55.55)^4] + 1.957 x (343 - 304)^1.25 x sqrt[(196.85 x 3.5 + 68.9)/68.9] = 937.62 W/m2","explain":"The formula uses surface and ambient temperatures in Kelvin for the radiation part. The convection part uses the temperature difference, scaled by wind speed."},{"prompt":"Convert to kcal per m2 per hour.","answer":"937.62 x 0.86 = 806.35 kcal/m2 h","explain":"1 W = 0.86 kcal/h, so the conversion is done with 0.86."},{"prompt":"Find the total loss per hour.","answer":"806.35 x 90 m2 = 72,571.6 kcal/h","explain":"Total loss is per-square-metre loss times the total surface area."},{"prompt":"Express as % of heat input.","answer":"72,571.6 / (3501 x 5600) x 100 = 0.37%","explain":"Heat input per hour is coal GCV times coal flow rate: 3501 x 5600 kcal/h."}],"order":4117},
{"id":"p4-b01-039","paper":4,"topic":"Boiler Performance","kind":"problem","front":"In the coal boiler example, 10% of total ash goes to bottom ash (GCV 800 kcal/kg) and 90% to fly ash (GCV 450 kcal/kg). Ash content is 48%. Find the % heat loss in fly ash and bottom ash (coal GCV 3501 kcal/kg).","back":"Fly ash loss = 0.62%. Bottom ash loss = 9.87%.","explain":"Ash losses are heat in unburnt carbon per kg of coal, divided by coal GCV. Bottom ash is the large loss here because it holds 90% of the ash and has a higher GCV.","flash":false,"source":"BEE Book 4 Ch 01 p37","steps":[{"prompt":"Find fly ash quantity per kg of coal and its heat loss.","answer":"0.1 x 0.48 = 0.048 kg/kg coal; 0.048 x 450 = 21.6 kcal/kg coal","explain":"Fly ash is 10% of total ash. Its heat is the mass times its GCV."},{"prompt":"Find bottom ash quantity per kg of coal and its heat loss.","answer":"0.9 x 0.48 = 0.432 kg/kg coal; 0.432 x 800 = 345.6 kcal/kg coal","explain":"Bottom ash is 90% of total ash and has the higher GCV of 800 kcal/kg."},{"prompt":"Convert to % of coal GCV.","answer":"Fly ash = 21.6 / 3501 x 100 = 0.62%; bottom ash = 345.6 / 3501 x 100 = 9.87%","explain":"Dividing by coal GCV puts the ash losses on the same basis as the other losses."}],"order":4118},
{"id":"p4-b01-040","paper":4,"topic":"Boiler Performance","kind":"problem","front":"A boiler flue gas has CO = 0.55% and CO2 = 14%, with 0.36 kg carbon per kg coal and GCV 3501 kcal/kg. Find the % heat loss due to partial conversion of carbon to CO.","back":"About 2.2%.","explain":"Each kg of carbon burnt only to CO loses heat that would otherwise be released by burning to CO2. The book's constant 5654 is kcal per kg of carbon, and the flue gas ratio gives the fraction of carbon burnt to CO.","flash":false,"source":"BEE Book 4 Ch 01 p33","steps":[{"prompt":"Write the formula.","answer":"L5 = [%CO x C / (%CO + %CO2)] x 5654 / GCV x 100","explain":"The ratio %CO / (%CO + %CO2) is the share of carbon that left as CO rather than CO2."},{"prompt":"Substitute the values.","answer":"0.55 x 0.36 / (0.55 + 14) x 5654 / 3501 x 100","explain":"C = 0.36 kg carbon per kg coal; the 5654 is heat lost per kg carbon burnt to CO instead of CO2."},{"prompt":"Evaluate.","answer":"= 0.0136 x 5654 / 3501 x 100 = 2.2%","explain":"A small CO reading can still cost about 2% of input energy when the carbon content is high."}],"order":4119},
{"id":"p4-b01-041","paper":4,"topic":"Boiler Performance","kind":"problem","front":"An oil-fired boiler burns 2,650 kg/h of fuel with GCV 10,000 kcal/kg. Its surface area is 90 m2 and surface temperature 80 °C; ambient 30 °C; wind 3.8 m/s. Find the radiation and convection loss as a % of heat input.","back":"0.38%.","explain":"This follows the same formula used for the coal boiler, with different temperatures and wind speed. The result is well below the 0.5 to 1% simple assumption the book gives for quick calculations.","flash":false,"source":"BEE Book 4 Ch 01 p40","steps":[{"prompt":"Find the loss per m2 from the formula.","answer":"L = 0.548 x [(353/55.55)^4 - (303/55.55)^4] + 1.957 x (353 - 303)^1.25 x sqrt[(196.85 x 3.8 + 68.9)/68.9] = 1303 W/m2","explain":"Temperatures are converted to Kelvin: 80 C = 353 K and 30 C = 303 K."},{"prompt":"Convert and find total loss per hour.","answer":"1303 x 0.86 = 1120.58 kcal/m2 h; x 90 m2 = 100,852 kcal/h","explain":"Same conversion as the coal case: W to kcal/h then multiplied by area."},{"prompt":"Express as % of heat input.","answer":"100,852 / (10000 x 2650) x 100 = 0.38%","explain":"Heat input per hour = GCV x fuel flow rate."}],"order":4120},
{"id":"p4-b02-001","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What is the difference between batch-type and continuous-type industrial heating furnaces?","back":"Batch furnaces hold the job stationary (box, bogie, cover types). Continuous furnaces deliver large volumes of work at regular intervals (pusher, walking hearth, rotary hearth, walking beam).","explain":"The book says continuous furnaces are used in general for mass production. The book names batch types by their stationary-job design.","flash":false,"source":"BEE Book 4 Ch 02 p49","order":4121},
{"id":"p4-b02-002","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What primary energy sources do reheating and annealing furnaces use?","back":"Furnace oil, LSHS, LDO or electricity.","explain":"The chapter treats these as the primary energy inputs for reheating and heat-treatment furnaces. The efficiency and specific energy calculations use the same input units.","flash":false,"source":"BEE Book 4 Ch 02 p49","order":4122},
{"id":"p4-b02-003","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What are the three aims of a furnace performance test?","back":"To make a heat balance of the furnace; to find its efficiency; to find its specific energy consumption.","explain":"Results are compared with design values or best-practice norms. Performance testing is the key to assessing current performance and finding improvement potential.","flash":true,"source":"BEE Book 4 Ch 02 p50","order":4123},
{"id":"p4-b02-004","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Which Japanese standard covers heat balance for continuous steel reheating furnaces?","back":"JIS G0702, Method of heat balance for continuous furnaces for steel. It was simplified for practical calculation in industry.","explain":"The book uses this standard to establish heat losses and efficiency of reheating furnaces. Conventional methods are also used.","flash":false,"source":"BEE Book 4 Ch 02 p49","order":4124},
{"id":"p4-b02-005","paper":4,"topic":"Furnace Performance","kind":"fact","front":"How is furnace efficiency defined?","back":"Efficiency = heat in the stock (material) / heat in the fuel or electricity consumed, x 100.","explain":"It is the ratio of useful heat output to total heat input. The direct method measures it this way.","flash":false,"source":"BEE Book 4 Ch 02 p50","order":4125},
{"id":"p4-b02-006","paper":4,"topic":"Furnace Performance","kind":"fact","front":"How is specific energy consumption (SEC) of a furnace defined?","back":"Amount of energy consumed (kcal/h) divided by quantity of material processed (t/h).","explain":"SEC is a per-tonne measure, so furnaces of different capacity can be compared. The book uses it as a better comparison than efficiency alone.","flash":false,"source":"BEE Book 4 Ch 02 p50","order":4126},
{"id":"p4-b02-007","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Why is a heat balance a pre-requisite for assessing energy conservation potential?","back":"It numerically shows the present heat losses and efficiency, so the operation can be improved using those data.","explain":"Without a heat balance, you cannot tell which loss is worth tackling. The heat balance is the starting point for any furnace energy-saving project.","flash":false,"source":"BEE Book 4 Ch 02 p50","order":4127},
{"id":"p4-b02-008","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Name the four major losses in a fuel-fired furnace.","back":"1. Heat lost in exhaust gases (sensible heat or incomplete combustion); 2. heat lost through furnace walls and hearth; 3. radiation and convection from the outer wall surface; 4. gases leaking through cracks, openings and doors.","explain":"These are the losses the book lists before the heat balance. Each one is then calculated separately in the heat balance table.","flash":true,"source":"BEE Book 4 Ch 02 p50","order":4128},
{"id":"p4-b02-009","paper":4,"topic":"Furnace Performance","kind":"fact","front":"How is furnace efficiency found from a heat balance?","back":"Subtract from heat input the sensible heat loss in flue gas, the loss from moisture in flue gas, heat loss through openings, heat loss through furnace skin, and other unaccounted losses.","explain":"This is the same logic as the indirect boiler method. Losses are added up and subtracted from the input heat.","flash":false,"source":"BEE Book 4 Ch 02 p50","order":4129},
{"id":"p4-b02-010","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What key measurements are needed for an oil-fired reheating furnace energy balance?","back":"Weight of stock or number of billets heated; temperature of stock; temperature of furnace walls and roof; area of furnace walls and roof; flue gas temperature; flue gas analysis; fuel oil consumption.","explain":"Reference data such as specific heat and humidity are taken from a data book or reference manual, not measured.","flash":false,"source":"BEE Book 4 Ch 02 p51","order":4130},
{"id":"p4-b02-011","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Which instruments are used to measure furnace heat-balance parameters?","back":"Infrared thermometer, fuel consumption monitor, surface thermocouple and other measuring devices.","explain":"The fuel consumption monitor gives the fuel flow used in the specific fuel consumption calculation. The book lists the instruments against the parameters they measure.","flash":false,"source":"BEE Book 4 Ch 02 p51","order":4131},
{"id":"p4-b02-012","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What formula gives the heat imparted to the stock in a furnace?","back":"Q = m x Cp x (t2 - t1), where m = weight of material (kg), Cp = mean specific heat (kcal/kg °C), t2 = final desired temperature (°C), t1 = initial charge temperature (°C).","explain":"Heat to the stock is the useful output. If the material changes state, latent heat of fusion or evaporation must be added to the total.","flash":false,"source":"BEE Book 4 Ch 02 p51","order":4132},
{"id":"p4-b02-013","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Why must latent heat be added when the process changes a material from solid to liquid or liquid to gas?","back":"Latent heat of fusion or evaporation is extra energy needed to change state. It is added on top of sensible heat in the total energy requirement.","explain":"Sensible heat alone is not enough to melt or vaporise a material. Missing the latent heat term understates the energy required.","flash":false,"source":"BEE Book 4 Ch 02 p51","order":4133},
{"id":"p4-b02-014","paper":4,"topic":"Furnace Performance","kind":"fact","front":"How does heat transfer by radiation vary with absolute temperature?","back":"It is proportional to the fourth power of absolute temperature, so radiation losses rise steeply as temperature increases.","explain":"Because of the fourth-power law, a small rise in furnace temperature can greatly increase radiation loss. This is why open doors at high temperature are costly.","flash":true,"source":"BEE Book 4 Ch 02 p59","order":4134},
{"id":"p4-b02-015","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What practical advice does the book give for steel melters to cut radiation losses?","back":"Keep the furnace lid closed at all times and keep a continuous feed of cold charge onto the molten bath.","explain":"Radiation from an open door at 1500 °C is about 11 times that at 700 °C, so closing the lid and feeding continuously reduces the number of hours the door is open.","flash":true,"source":"BEE Book 4 Ch 02 p59","order":4135},
{"id":"p4-b02-016","paper":4,"topic":"Furnace Performance","kind":"fact","front":"How does furnace utilisation affect efficiency?","back":"If the furnace is held at temperature, standby losses occur whether or not product is in it. Low utilisation therefore lowers efficiency and is often underestimated.","explain":"A furnace at temperature loses heat by conduction, convection and radiation even when empty. Keeping production high reduces the share of standby loss per tonne.","flash":true,"source":"BEE Book 4 Ch 02 p60","order":4136},
{"id":"p4-b02-017","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What are the three ways heat is lost from a charge or its enclosure?","back":"Conduction, convection, and radiation.","explain":"These mechanisms drive standby losses from the furnace enclosure. Each depends on temperature and surface area.","flash":true,"source":"BEE Book 4 Ch 02 p60","order":4137},
{"id":"p4-b02-018","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What is scale in a reheating furnace, and how does it cause loss?","back":"Scale is the flaky material formed by oxidation of iron or steel at high temperature in the presence of excess air. It causes material loss and so reduces useful output.","explain":"Scale is lost metal, so the loss is both fuel and material. The book names excess air and high temperature as the conditions that cause it.","flash":false,"source":"BEE Book 4 Ch 02 p60","order":4138},
{"id":"p4-b02-019","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What list of factors affecting furnace performance does the book give?","back":"Under-loading from poor hearth loading or poor scheduling; improper design; inefficient burners; insufficient draft or chimney; no waste heat recovery; absence of instruments and controls; improper operation and maintenance; high stack loss; improper insulation or refractories.","explain":"These are the factors an auditor checks first when a furnace underperforms. Under-loading and missing heat recovery are often the largest.","flash":false,"source":"BEE Book 4 Ch 02 p59","order":4139},
{"id":"p4-b02-020","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Which heat-loss formula applies to an opening (door or hole) in a furnace wall?","back":"Q = hr x A x Phi x 4.88 x [(T/100)^4 - (T0/100)^4] / t, where hr = open time, A = opening area (m2), Phi = shape coefficient, T = furnace temperature (K), T0 = base temperature (K), t = tonnes of billet per hour.","explain":"The shape coefficient Phi depends on the opening profile and wall thickness. The worked example uses a square opening with coefficient 0.70 at ratio 2.17.","flash":false,"source":"BEE Book 4 Ch 02 p57","order":4140},
{"id":"p4-b02-021","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What natural-convection heat-transfer coefficients does the worked example use for the furnace ceiling, side walls and flue duct?","back":"Ceiling 2.8; side walls 2.2; flue duct 1.1 (all kcal/m2 h °C).","explain":"These coefficients are used with the temperature difference raised to the power 1.25. The surface emissivity used in the example is 0.75.","flash":false,"source":"BEE Book 4 Ch 02 p56","order":4141},
{"id":"p4-b02-022","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Why is the furnace bottom surface left out of the body heat loss calculation?","back":"Because the bottom faces downward and is not exposed to the atmosphere, so its loss is ignored.","explain":"The body loss counts only surfaces that lose heat to the room: the ceiling, side walls and flue duct.","flash":false,"source":"BEE Book 4 Ch 02 p57","order":4142},
{"id":"p4-b02-023","paper":4,"topic":"Furnace Performance","kind":"fact","front":"List the unaccounted (other) heat losses in a furnace heat balance.","back":"Heat carried away by cooling water in the flue damper; cooling water at the furnace access door; radiation from the furnace bottom; heat accumulated by refractory; instrumental and measuring error; others.","explain":"Unaccounted losses are found as the difference between total heat input and the sum of all measured losses. Large unaccounted losses point to measurement error or a missed loss.","flash":false,"source":"BEE Book 4 Ch 02 p58","order":4143},
{"id":"p4-b02-024","paper":4,"topic":"Furnace Performance","kind":"fact","front":"What is the specific heat of dry flue gas at 655 °C and at 40 °C from the worked example?","back":"0.26 kcal/kg °C at 655 °C; 0.24 kcal/kg °C at 40 °C.","explain":"The mean value 0.26 is used for the dry flue gas loss between 40 °C and 655 °C. The book builds each value from the component gas specific heats in a table.","flash":false,"source":"BEE Book 4 Ch 02 p62","order":4144},
{"id":"p4-b02-025","paper":4,"topic":"Furnace Performance","kind":"fact","front":"How is a partial specific heat of a flue gas component calculated?","back":"Partial Cp = (mass fraction x specific heat x 22.4) / molecular weight. The dry flue gas specific heat is the sum of all partial values.","explain":"The 22.4 converts the gas specific heat from per cubic metre to per kmol. Each gas is summed to give the mean dry flue gas specific heat.","flash":false,"source":"BEE Book 4 Ch 02 p62","order":4145},
{"id":"p4-b02-026","paper":4,"topic":"Furnace Performance","kind":"fact","front":"Which damper or pressure setting reduces air ingress and can raise furnace efficiency?","back":"Running the fuel-fired furnace at a slight positive pressure reduces air ingress and can increase efficiency.","explain":"Negative pressure draws cold air through cracks and doors, which adds to the heat that must be heated and carried out of the furnace.","flash":true,"source":"BEE Book 4 Ch 02 p60","order":4146},
{"id":"p4-b02-027","paper":4,"topic":"Furnace Performance","kind":"problem","front":"An oil-fired reheating furnace heats 6 t/h of billets (from 40 °C to 1340 °C, Cp 0.12 kcal/kg °C) using 368 kg/h of oil (GCV 10,000 kcal/kg). Find the furnace efficiency based on heat carried away by the billet.","back":"Efficiency = 25.4%.","explain":"Furnace efficiency here is heat to load per tonne divided by combustion heat per tonne. The rest of the heat is lost through flue gas, openings and walls.","flash":false,"source":"BEE Book 4 Ch 02 p59","steps":[{"prompt":"Find the heat carried away by the billet per tonne.","answer":"Q3 = 1000 x 0.12 x (1340 - 40) = 156,000 kcal/t","explain":"Heat to load = mass per tonne x specific heat x temperature rise."},{"prompt":"Find the combustion heat of fuel per tonne.","answer":"Fuel per tonne = 368 / 6 = 61.33 kg/t; combustion heat = 61.33 x 10,000 = 613,300 kcal/t","explain":"Specific fuel consumption is the fuel per tonne of billet, multiplied by the oil GCV."},{"prompt":"Compute the efficiency.","answer":"156,000 / 613,300 x 100 = 25.4%","explain":"This is the book's definition of furnace efficiency: heat to load divided by combustion heat of the fuel."}],"order":4147},
{"id":"p4-b02-028","paper":4,"topic":"Furnace Performance","kind":"problem","front":"Using the same oil-fired reheating furnace (368 kg/h of oil, 6 t/h of billet), find the specific fuel consumption in kg of fuel per tonne of billet.","back":"61.33 kg of fuel per tonne of billet.","explain":"Specific fuel consumption is fuel used per hour divided by billet throughput per hour. It is used to compare furnaces of different sizes.","flash":false,"source":"BEE Book 4 Ch 02 p54","steps":[{"prompt":"Write the formula.","answer":"Specific fuel consumption (F) = amount of fuel consumed (kg/h) / amount of billet (t/h)","explain":"Both quantities are per hour, so the result is per tonne of billet."},{"prompt":"Convert the fuel flow to mass.","answer":"400 litres/h x 0.92 kg/litre = 368 kg/h","explain":"Oil is measured by volume but the heat balance works in mass, so the specific gravity converts it."},{"prompt":"Compute F.","answer":"368 / 6 = 61.33 kg of fuel per tonne of billet","explain":"Specific fuel consumption is used later to scale every heat loss to one tonne of billet."}],"order":4148},
{"id":"p4-b02-029","paper":4,"topic":"Furnace Performance","kind":"problem","front":"For the same furnace (fuel 61.33 kg per tonne of billet, GCV 10,000 kcal/kg, sensible heat in fuel at 100 °C preheat), find the total heat input per tonne of billet.","back":"Total heat input = 615,140 kcal per tonne of billet (combustion heat 613,300 plus sensible heat 1,840).","explain":"Combustion heat is the main input, but the sensible heat of the preheated fuel adds a small extra. The heat balance table uses this total as 100%.","flash":false,"source":"BEE Book 4 Ch 02 p54","steps":[{"prompt":"Find the combustion heat input per tonne.","answer":"61.33 x 10,000 = 613,300 kcal/t","explain":"Combustion heat = fuel per tonne x GCV."},{"prompt":"Find the sensible heat of the fuel per tonne.","answer":"Q2 = 61.33 x 0.5 x (100 - 40) = 1,840 kcal/t","explain":"Sensible heat = fuel per tonne x fuel specific heat x (fuel temperature - ambient). The fuel is preheated to 100 °C."},{"prompt":"Add the two inputs.","answer":"613,300 + 1,840 = 615,140 kcal/t","explain":"This total is the 100% basis for every loss in the heat balance table."}],"order":4149},
{"id":"p4-b02-030","paper":4,"topic":"Furnace Performance","kind":"problem","front":"Find the actual air supplied per kg of fuel for the oil-fired furnace (flue gas O2 12%, theoretical air 14.12 kg/kg fuel).","back":"Excess air = 133.3%; actual air supplied = 32.94 kg air per kg fuel.","explain":"Oxygen of 12% in flue gas means a very high excess, because 21% O2 is in air. Use the O2 formula, then multiply the theoretical air by (1 + EA/100).","flash":false,"source":"BEE Book 4 Ch 02 p55","steps":[{"prompt":"Find the excess air from measured O2.","answer":"EA = 12 / (21 - 12) x 100 = 133.3%","explain":"This is the same O2-based formula used for boilers, with 21% as O2 in ambient air."},{"prompt":"Find the actual air supplied.","answer":"AAS = (1 + 133.3/100) x 14.12 = 32.94 kg air/kg fuel","explain":"Actual air = theoretical air multiplied by (1 + excess air fraction)."}],"order":4150},
{"id":"p4-b02-031","paper":4,"topic":"Furnace Performance","kind":"problem","front":"For the same oil-fired furnace (AAS 32.94 kg/kg fuel, moisture 0.35%, hydrogen 12%, carbon 85.9%, sulphur 0.5%), find the mass of dry flue gas and the heat loss in dry flue gas per tonne of billet (flue gas 655 °C, ambient 40 °C, Cp 0.26 kcal/kg °C).","back":"Dry flue gas = 32.86 kg/kg fuel. Heat loss = 3,22,247 kcal per tonne of billet (about 52.4% of input).","explain":"Dry flue gas loss is the biggest single loss in the furnace heat balance. It is found from the total mass of dry flue gas times its specific heat and temperature rise.","flash":false,"source":"BEE Book 4 Ch 02 p54","steps":[{"prompt":"Find the wet flue gas mass.","answer":"AAS + 1 = 32.94 + 1 = 33.94 kg/kg fuel","explain":"Wet flue gas = actual air plus 1 kg fuel."},{"prompt":"Find the water vapour in flue gas.","answer":"M + 9H = 0.35/100 + 9 x 12/100 = 1.084 kg H2O/kg fuel","explain":"Water comes from moisture in the fuel and from hydrogen burning to water."},{"prompt":"Find the dry flue gas mass.","answer":"33.94 - 1.084 = 32.86 kg/kg fuel","explain":"Dry flue gas excludes the water vapour, which is calculated separately as a wet flue gas loss."},{"prompt":"Find the dry flue gas heat loss per tonne of billet.","answer":"Q4 = 61.33 x 32.86 x 0.26 x (655 - 40) = 3,22,247 kcal/t","explain":"Fuel per tonne x dry flue gas mass x specific heat x temperature rise above ambient."}],"order":4151},
{"id":"p4-b02-032","paper":4,"topic":"Furnace Performance","kind":"problem","front":"In the oil-fired furnace example, find the heat carried away by the furnace body (ceiling, side walls, flue duct) per tonne of billet. Ceiling 15 m2 at 85 °C, side walls 36 m2 at 100 °C, flue duct 10.3 m2 at 64 °C; ambient 40 °C; billet 6 t/h.","back":"Body loss = 6,122 kcal per tonne of billet (ceiling 8,644 + side walls 26,084 + flue duct 2,001 kcal/h, divided by 6 t/h).","explain":"Each surface loses heat by natural convection and radiation. The bottom is excluded because it is not exposed. The total per hour is converted to per tonne by dividing by billet output.","flash":false,"source":"BEE Book 4 Ch 02 p56","steps":[{"prompt":"Find the ceiling loss per hour.","answer":"Convection: 2.8 x 45^1.25 x 15 = about 4,892 kcal/h; radiation: 4.88 x 0.75 x [(358/100)^4 - (313/100)^4] x 15 = about 3,744 kcal/h; sum about 8,636, which the book rounds to 8,644 kcal/h","explain":"Ceiling temperature 85 C = 358 K; room 40 C = 313 K; temperature difference 45 K."},{"prompt":"Find the side-wall and flue-duct losses per hour.","answer":"Side walls = 26,084 kcal/h; flue duct = 2,001 kcal/h (book)","explain":"Side walls at 100 C use a convection coefficient of 2.2; flue duct uses 1.1 with its outside diameter 0.4 m."},{"prompt":"Convert the total to per tonne of billet.","answer":"(8,644 + 26,084 + 0 + 2,001) / 6 = 6,122 kcal/t","explain":"Bottom loss is zero because it is not exposed to the atmosphere."}],"order":4152}
]$cards$::jsonb);
